void mergeSort(int st, int dr) {
    if (st >= dr) return;
    int m = (st + dr) / 2;
    mergeSort(st, m);
    mergeSort(m + 1, dr);
    int i = st, j = m + 1, k = st;
    while (i <= m && j <= dr) {
        if (v[i] <= v[j]) tmp[k++] = v[i++];
        else tmp[k++] = v[j++];
