#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;
int n, m;
vector<vector<long long>> s; // s[i][j] = suma primelor j elemente de pe linia i

long long sumaLinie(int i, int y1, int y2) { return s[i][y2] - s[i][y1 - 1]; }

// rația progresiei formate de sumele pe linii, sau 0 dacă nu există
long long ratie(int x1, int y1, int x2, int y2) {
    vector<long long> v;
    for (int i = x1; i <= x2; i++) v.push_back(sumaLinie(i, y1, y2));
    sort(v.begin(), v.end());
    long long r = v[1] - v[0];
    if (r == 0) return 0;
    for (size_t k = 2; k < v.size(); k++)
        if (v[k] - v[k - 1] != r) return 0;
    return r;
}

void comprima(int x1, int y1, int x2, int y2) {
    long long r = 0;
    if (x1 < x2 && y1 < y2) {
        r = ratie(x1, y1, x2, y2);
        if (r == 0) {
            int mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
            cout << "(";
            comprima(x1, y1, mx, my);
            comprima(x1, my + 1, mx, y2);
            comprima(mx + 1, y1, x2, my);
            comprima(mx + 1, my + 1, x2, y2);
            cout << ")";
            return;
        }
    }
    cout << "(" << x1 << "," << y1 << "," << x2 << "," << y2 << "," << r << ")";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int c;
    cin >> c >> n >> m;
    s.assign(n + 1, vector<long long>(m + 1, 0));
    vector<vector<long long>> a(n + 1, vector<long long>(m + 1));
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            cin >> a[i][j];
            s[i][j] = s[i][j - 1] + a[i][j];
        }
    if (c == 1) {
        long long best = s[1][m];
        for (int i = 2; i <= n; i++) best = max(best, s[i][m]);
        for (int i = 1; i <= n; i++)
            if (s[i][m] == best) cout << i << "\n";
    } else if (c == 2) {
        bool gasit = false;
        for (int i = 1; i <= n; i++) {
            vector<long long> v(a[i].begin() + 1, a[i].end());
            sort(v.begin(), v.end());
            bool ok = m >= 2 && v[1] != v[0];
            for (int k = 2; k < m && ok; k++)
                if (v[k] - v[k - 1] != v[1] - v[0]) ok = false;
            if (ok) {
                cout << i << "\n";
                gasit = true;
            }
        }
        if (!gasit) cout << 0 << "\n";
    } else {
        comprima(1, 1, n, m);
        cout << "\n";
    }
    return 0;
}

