#include <iostream>
using namespace std;
const long long INF = 1e18;
int n;
long long b[1005][1005], f[1005][1005];
long long e[1005]; // e[i] = câștigul maxim cu care se intră în celula (i, d - i)
int main() {
    cin >> n;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) cin >> b[i][j];
    // pe o diagonală i + j = d mutările (i+1, j-1) și (i-1, j+1) rămân pe diagonală,
    // iar (i, j+1) și (i+1, j) trec pe diagonala următoare
    for (int d = 2; d <= 2 * n; d++) {
        int lo = max(1, d - n), hi = min(n, d - 1);
        for (int i = lo; i <= hi; i++) {
            int j = d - i;
            if (d == 2) e[i] = 0;
            else {
                e[i] = -INF;
                if (j > 1) e[i] = max(e[i], f[i][j - 1]);
                if (i > 1) e[i] = max(e[i], f[i - 1][j]);
            }
        }
        // se intră în celula e și se merge de-a lungul diagonalei până la i, într-un singur sens
        long long best = -INF;
        for (int i = lo; i <= hi; i++) { // în jos-stânga (i crește)
            best = max(best, e[i]) + b[i][d - i];
            f[i][d - i] = best;
        }
        best = -INF;
        for (int i = hi; i >= lo; i--) { // în sus-dreapta (i scade)
            best = max(best, e[i]) + b[i][d - i];
            f[i][d - i] = max(f[i][d - i], best);
        }
    }
    cout << f[n][n];
    return 0;
}

