        vector<int> d(n + 1, -1);
        queue<int> q;
        d[a] = 0;
        q.push(a);
        while (!q.empty() && d[b] == -1) {
            int x = q.front();
            q.pop();
            for (int k = 0; k < 3; k++) {
                int v = p[x][k];
                if (folosita[v]) continue;
                folosita[v] = true;
                for (int y : cu[v])
                    if (d[y] == -1) {
                        d[y] = d[x] + 1;
                        q.push(y);
                    }
            }
        }
        cout << d[b] << "\n";
        for (int i = 1; i <= n; i++)
            for (int k = 0; k < 3; k++) {
                cu[p[i][k]].clear();
                folosita[p[i][k]] = false;
            }
    }
    return 0;
}
